CREATE TABLE `pull_requests` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `github_number` bigint DEFAULT NULL,
  `update_job_id` bigint NOT NULL,
  `repo_id` bigint NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `head_commit_sha` varchar(40) COLLATE utf8mb4_general_ci NOT NULL,
  `head_commit_ci_status` varchar(40) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `base_commit_sha` varchar(40) COLLATE utf8mb4_general_ci NOT NULL,
  `base_commit_ci_status` varchar(40) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `multiple_dependencies` tinyint(1) NOT NULL,
  `merge_requested` tinyint(1) NOT NULL DEFAULT '0',
  `dependabot_commit_sha` varchar(40) COLLATE utf8mb4_general_ci NOT NULL,
  `dependabot_commit_ci_status` varchar(40) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `squash_requested` tinyint(1) NOT NULL DEFAULT '0',
  `automerge_block_requested` tinyint(1) NOT NULL DEFAULT '0',
  `update_config_id` bigint NOT NULL,
  `grouped_update` tinyint(1) DEFAULT '0',
  `dependency_group_id` bigint DEFAULT NULL,
  `affected_directories` text COLLATE utf8mb4_general_ci,
  `current_state` varchar(40) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `index_pull_requests_on_repo_id_and_github_number` (`repo_id`,`github_number`),
  KEY `index_pull_requests_on_head_commit_sha` (`head_commit_sha`),
  KEY `index_pull_requests_on_update_job_id` (`update_job_id`),
  KEY `index_existing_pull_check` (`update_config_id`,`grouped_update`,`multiple_dependencies`),
  KEY `index_pull_requests_on_dependency_group_id` (`dependency_group_id`),
  KEY `index_pull_requests_on_current_state_and_update_config_id` (`current_state`,`update_config_id`),
  KEY `index_pull_requests_on_current_state_and_repo_id` (`current_state`,`repo_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
